    var allowedHosts = ['heatcalc.ru', 'www.heatcalc.ru', 'new.heatcalc.ru', 'terem24.github.io', 'localhost', '127.0.0.1'];

    // Если текущего домена нет в списке разрешенных (включая запуск из папки через file://)
