const supabaseUrl = 'https://ahanbwugsmcyvrwbmtlx.supabase.co';
const supabaseKey = 'sb_publishable_gcMJ-PvJmKavObbnePFGZQ_O-pu5O2p';

// У части пользователей в РФ провайдер блокирует/дросселирует Cloudflare (за которым стоит
// Supabase), из-за чего запросы к *.supabase.co не доходят из браузера ("Нет связи с сервером"
// при исправном проекте и коде). Раньше прокси лежал прямо на heatcalc.ru (supabase_proxy.php),
// но GitHub Pages, на котором раздаётся сайт, не исполняет PHP — прокси всегда отдавал
// исходный код вместо ответа и ломал вход у всех. Теперь прокси вынесен на отдельный
// поддомен proxy.heatcalc.ru с настоящим PHP-хостингом (Beget), сам сайт остаётся на GitHub Pages.
function supabaseProxyFetch(input, init) {
    const url0 = typeof input === 'string' ? input : input.url;
    // Предел ожидания. На телефоне запрос, начатый перед сворачиванием или сменой
    // сети, мог не вернуться никогда. Если это было обновление входа (/auth/),
    // библиотека держит на нём общую очередь, и за ним вставали все обращения к
    // базе: отправил одно сообщение — кнопка серая до перезахода. С пределом
    // повисший запрос падает ошибкой, библиотека повторяет его сама, очередь идёт.
    // Файлы (/storage/) и функции не ограничиваем: крупная загрузка честно долгая.
    const limitMs = /\/auth\/v1\//.test(url0) ? 15000 : (/\/rest\/v1\//.test(url0) ? 40000 : 0);
    if (limitMs && typeof AbortController !== 'undefined') {
        const ctrl = new AbortController();
        const outer = init && init.signal;
        if (outer) {
            if (outer.aborted) ctrl.abort();
            else outer.addEventListener('abort', () => ctrl.abort(), { once: true });
        }
        const timer = setTimeout(() => ctrl.abort(), limitMs);
        return supabaseProxyFetchRaw(input, Object.assign({}, init, { signal: ctrl.signal }))
            .finally(() => clearTimeout(timer));
    }
    return supabaseProxyFetchRaw(input, init);
}
function supabaseProxyFetchRaw(input, init) {
    const host = window.location.hostname;
    // new.heatcalc.ru — проверочная копия сайта на Beget (см. allowedHosts выше).
    // Через прокси её пускаем по той же причине, что и основной адрес: иначе
    // проверка шла бы в других условиях, чем работа, и «вход не работает» на
    // копии значило бы не то же самое, что на сайте.
    // Приложение для Android открывает страницу с https://localhost и до этого ходило
    // в базу напрямую: у части провайдеров supabase.co не открывается, и вкладки
    // админки висели до обрыва по времени («AbortError: signal is aborted…»).
    // Его тоже пускаем через прокси — как сам сайт. Локальную разработку
    // (http://localhost:8080) это не задевает: у неё протокол http.
    const inApp = !!window.__HC_NATIVE__ || (host === 'localhost' && window.location.protocol === 'https:');
    const canProxy = inApp || (host === 'heatcalc.ru' || host === 'www.heatcalc.ru' || host === 'new.heatcalc.ru');
    const url = typeof input === 'string' ? input : input.url;
    if (canProxy && url.startsWith(supabaseUrl)) {
        return fetch('https://proxy.heatcalc.ru/supabase_proxy.php?path=' + encodeURIComponent(url.slice(supabaseUrl.length)), init);
    }
    return fetch(input, init);
}

// Ссылка из письма «Сброс пароля» открывает сайт с #…&type=recovery в адресе.
// Метку снимаем ДО создания клиента: Supabase разбирает адрес прямо в конструкторе
// и стирает его, а событие PASSWORD_RECOVERY выстреливает раньше, чем app.init
// успевает на него подписаться. Без этой метки ссылка молча впускала человека в
// аккаунт, а окна с новым паролем не было — и пароль он так и не узнавал.
const HC_PASSWORD_RECOVERY = /(^|[#&?])type=recovery(&|$)/.test(
    (window.location.hash || '').replace(/^#/, '') + '&' + (window.location.search || '').replace(/^\?/, '')
);

const supabaseClient = supabase.createClient(supabaseUrl, supabaseKey, {
    global: { fetch: supabaseProxyFetch }
});




