/**
 * Сжимает описание позиции (подсказка ⓘ) для клиентской ссылки.
 *
 * Описания — самая тяжёлая часть ссылки: на смете из 20 позиций они занимали
 * почти 88% данных. Причина не в тегах (одинаковые обёртки deflate схлопывает
 * почти в ноль), а в самом тексте: формулы подбора, подставленные значения,
 * паспортные характеристики. Всё это — обоснование для монтажника, клиенту оно
 * не нужно, поэтому в ссылку уходит только заголовок и абзац «Зачем». Разметку
 * заменяем однобуквенными метками; invoice.html разворачивает их обратно
 * (expandDesc). Вместе это укоротило ссылку примерно вдвое.
 *
 * Метки: §заголовок в первой строке, ¦…¬ вместо <b>…</b>, перевод строки
 * вместо <br>. Ни один из трёх символов в текстах описаний не встречается.
 */
function compactDesc(desc) {
    if (!desc) return '';
    let s = String(desc);

    // 1. Снимаем внешнюю обёртку и вынимаем заголовок (синяя строка с чертой).
    let title = '';
    const wrapped = s.match(/^<span style="font-size:11px;[^"]*">([\s\S]*)<\/span>$/);
    if (wrapped) {
        s = wrapped[1];
        const head = s.match(/^<span style="font-weight:700; color:#93C5FD;[^"]*">([\s\S]*?)<\/span>/);
        if (head) {
            title = head[1];
            s = s.slice(head[0].length);
        }
    }

    // 2. Оставляем только «Зачем». Шаблонов два: абзацы <div class="tip-p">
    //    (autoTip) и сплошной текст с <br> (getDesc). Если абзаца «Зачем» нет
    //    вовсе — это короткое описание фитинга, оставляем его целиком.
    const paras = s.match(/<div class="tip-p">[\s\S]*?<\/div>/g);
    if (paras) {
        const why = paras.filter(p => p.indexOf('<b>Зачем:</b>') !== -1);
        if (why.length) s = why.join('');
    } else {
        const at = s.indexOf('<b>Зачем:</b>');
        if (at !== -1) {
            const tail = s.slice(at + 13);
            const end = tail.search(/<br|<b[ >]|<i[ >]|<div/);
            s = '<b>Зачем:</b>' + (end === -1 ? tail : tail.slice(0, end));
        }
    }

    // 3. Разметку — в метки, всё нераспознанное выбрасываем.
    s = s.replace(/<br\s*\/?>/g, '\n')
        .replace(/<\/div>/g, '\n')
        .replace(/<b[^>]*>/g, '¦')
        .replace(/<\/b>/g, '¬')
        .replace(/<[^>]+>/g, '')
        .replace(/\n{2,}/g, '\n')
        .trim();

    return (title ? '§' + title + '\n' : '') + s;
}

/**
 * Что найдёт invoice.html по этому артикулу в catalog.js — или null.
 *
 * Повторяет findCatalogItem оттуда: только верхний уровень catalog[key]
 * (массив или одиночный объект) плюс вложенная ROMMER-версия. Всё, что лежит
 * вне объекта catalog, страница не видит: радиаторные линейки (titanRads,
 * steelRads и остальные отдельные массивы), radAccessories, а главное —
 * распознанные позиции: их артикул чаще всего из прайса, а не из каталога,
 * либо артикула нет вовсе. У обычной строки в ссылку уходит один артикул, и
 * цену страница берёт из каталога — для таких позиций она получала пусто и
 * показывала клиенту 0 ₽ при правильном итоге в шапке.
 */
function shareLinkCatalogFind(sku) {
    if (!sku || typeof catalog === 'undefined') return null;
    for (const key in catalog) {
        const list = catalog[key];
        if (!list) continue;
        const arr = Array.isArray(list) ? list : [list];
        for (const it of arr) {
            if (!it) continue;
            if (it.id === sku || it.article === sku) return it;
            const r = it.rommer;
            if (r) {
                if (Array.isArray(r)) {
                    const hit = r.find(x => x && x.id === sku);
                    if (hit) return hit;
                } else if (r.id === sku) {
                    return r;
                }
            }
        }
    }
    return null;
}

/**
 * Артикул позиции или пусто, если артикула у неё нет.
 *
 * У позиции каталога id и есть артикул, а вот распознанные ('rec_…') и
 * добавленные монтажником ('custom_…', 'user_…') строки живут под служебным
 * id. Он не значит ничего ни для клиента, ни для 1С, но раньше подставлялся
 * в колонку «Артикул» запасным вариантом — и клиент получал счёт со строкой
 * 'custom_1786965434808'.
 */
function realSku(id) {
    const s = String(id || '');
    return /^(rec|custom|user)_/.test(s) ? '' : s;
}

function compactPayload(data) {
    const SECTION_MAP = {
        "1. Котёл + водонагреватель": 1,
        "2. Обвязка котельной": 2,
        "3. Радиаторное отопление": 3,
        "4. Водяной теплый пол": 4,
        "5. Горячее водоснабжение": 5,
        "6. Водопровод и канализация": 6,
        "7. Управление отоплением": 7,
        "8. Монтажные элементы": 8,
        "9. Дополнительные материалы": 9,
        "10. Ввод ХВС и водоочистка": 10,
        "11. Скважина / Колодец": 11
    };

    return {
        o: {
            n: data.object_info.projectName || "Новый объект",
            a: data.object_info.area || 0,
            f: data.object_info.floors || 1,
            r: data.object_info.res || 1,
            m: data.object_info.mat || 1,
            p: data.object_info.power || 0,
            g: data.object_info.region || 'Центр',
            d: data.object_info.date || '',
            s: data.object_info.showSku ? 1 : 0,
            c: data.object_info.eqDiscount || 0,
            cw: data.object_info.worksDiscount || undefined,
            q: data.object_info.sequence_id || '',
            v: data.object_info.kp_version || 0,
            // Прайс-лист дистрибьютора. У обычных позиций в ссылку уходит только
            // артикул, а цену invoice.html берёт из каталога сам — без этого ключа
            // клиент увидел бы цены Терема, а итог в шапке был бы посчитан по ценам
            // дистрибьютора, и строки со сметой не сошлись бы.
            k: data.object_info.priceListKey || '',
            // Полные названия и артикулы (галочка «Без моделей и артикулов» снята)
            fn: data.object_info.fullNames ? 1 : undefined,
            // Срок действия счёта. Без этих полей длинная офлайн-ссылка (её
            // получает монтажник, когда Supabase не ответил за отведённое время)
            // открывалась без отсчёта: страница читает срок из ссылки, а строка
            // shared_invoices появляется позже, из очереди, и не проверяется.
            sa: data.object_info.sent_at || '',
            vd: data.object_info.valid_days == null ? undefined : data.object_info.valid_days,
            vu: data.object_info.valid_until || ''
        },
        m: {
            n: data.manager_info.name || '',
            p: data.manager_info.phone || '',
            c: data.manager_info.city || '',
            e: data.manager_info.email || ''
        },
        i: {
            e: (data.items.equipment || []).map(item => {
                const sku = item.displaySku || item.sku || item.id || '';
                const isCustom = item.id && String(item.id).startsWith('custom_');
                // Цену обычной позиции страница считает сама: цена каталога минус
                // скидка. Значит в ссылку можно не везти только те строки, где
                // получится ровно то же число. Не получается в двух случаях:
                //
                // 1. Позиции нет в catalog.js — страница не найдёт ничего и покажет
                //    0 ₽ (распознанное, радиаторы отдельных линеек, аксессуары).
                // 2. Цена строки посчитана, а не взята из каталога. Труба в
                //    теплоизоляции стоит в каталоге 220 ₽ за МЕТР, а в смету идёт
                //    строкой за бухту 100 м — 22 000 ₽. Страница считала бухту по
                //    цене метра, и клиент видел трубы в сто раз дешевле.
                //
                // В обоих случаях везём название и цену с собой, как у своей
                // позиции (c: 1), плюс артикул полем s — для колонки «Артикул» и
                // картинки. Цена уже со скидкой, страница её не пересчитывает.
                const hit = isCustom ? null : shareLinkCatalogFind(sku);
                const disc = data.object_info.eqDiscount || 0;
                const pagePrice = hit ? Math.round((hit.price || 0) * (1 - disc / 100)) : null;
                const isLoose = !isCustom && (!hit || pagePrice !== Math.round(item.price || 0));
                if (isCustom || isLoose) {
                    const out = {
                        n: item.name || '',
                        b: item.brand || '',
                        u: item.unit || '',
                        p: item.price || 0,
                        q: item.q || 0,
                        t: SECTION_MAP[item.sectionTitle] || item.sectionTitle || 9,
                        c: 1
                    };
                    if (isLoose) {
                        out.s = sku;
                        if (item.isOpt) out.o = 1;
                        out.d = compactDesc(item.desc);
                        // Наличие у таких строк тоже неоткуда взять — в отличие от
                        // обычных, где страница читает его из каталога. Правило
                        // 31 дня к нему уже применено в render().
                        if (item.availability) out.a = item.availability;
                    } else {
                        out.id = item.id;
                    }
                    return out;
                } else {
                    return {
                        s: sku,
                        q: item.q || 0,
                        t: SECTION_MAP[item.sectionTitle] || item.sectionTitle || 9,
                        o: item.isOpt ? 1 : 0,
                        d: compactDesc(item.desc)
                    };
                }
            }),
            w: (data.items.works || []).map(item => ({
                n: item.name || '',
                q: item.q || item.qty || 0,
                p: item.price || 0
            }))
        },
        t: {
            e: data.totals.equipment || 0,
            w: data.totals.works || 0,
            g: data.totals.grandTotal || 0
        }
    };
}

function base64Encode(str) {
    return btoa(encodeURIComponent(str).replace(/%([0-9A-F]{2})/g, function (match, p1) {
        return String.fromCharCode(parseInt(p1, 16));
    }));
}

async function compressString(str) {
    const byteArray = new TextEncoder().encode(str);
    const cs = new CompressionStream('deflate');
    const writer = cs.writable.getWriter();
    writer.write(byteArray);
    writer.close();
    const response = new Response(cs.readable);
    const arrayBuffer = await response.arrayBuffer();

    let binary = '';
    const bytes = new Uint8Array(arrayBuffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}

async function encodePayload(data) {
    const json = JSON.stringify(compactPayload(data));
    try {
        if (typeof CompressionStream !== 'undefined') {
            const compressed = await compressString(json);
            return 'c_' + encodeURIComponent(compressed);
        }
    } catch (e) {
        console.warn('CompressionStream failed, using raw base64:', e);
    }
    return 'r_' + encodeURIComponent(base64Encode(json));
}
