async function notifyPayment() {
    const emailEl = document.getElementById('userEmail');
    const emailInput = emailEl ? emailEl.value.trim() : '';
    const planNameEl = document.getElementById('planName');

    // Динамически получаем название тарифа со стоимостью из заголовка в модальном окне
    let tariffNameText = '';
    if (planNameEl) {
        // Убираем префикс "Тариф: ", если он присутствует
        tariffNameText = planNameEl.innerText.replace(/^Тариф:\s*/i, '').trim();
    }

    if (!emailInput) {
        app.alert('Пожалуйста, укажите ваш email, чтобы мы могли активировать статус Профи.');
        return;
    }

    // === 1. ОТПРАВКА В TELEGRAM ===
    const offered = app._currentPaymentPlan || null;
    const messageText = `Пользователь: ${emailInput}\nТариф: ${tariffNameText}`
        + (offered && offered.rub ? `\nК оплате: ${Math.round(offered.rub).toLocaleString('ru-RU')} ₽` : '')
        + (offered && offered.promo ? `\nАкция: ${offered.promo}` : '')
        + `\nПроверьте поступление в Т-Банке. Подтвердить: панель → «Оплата подписки».`;
    sendOwnerTelegram('pro_request', messageText);

    // === 1а. СТРОКА В УЧЁТЕ (вкладка «Оплата подписки») ===
    if (typeof Subscription !== 'undefined') {
        Subscription.logRequest({
            email: emailInput,
            plan: offered ? (offered.id || offered.type) : null,
            months: offered ? offered.months : null,
            rub: offered ? offered.rub : null,
            promo: offered ? offered.promo : null
        });
    }

    // === 2. ОТПРАВКА НА EMAIL (через EmailJS с обновленным шаблоном) ===
    const emailjsServiceID = 'service_o11b4ej';
    const emailjsTemplateID = 'template_ysuxfio';

    const templateParams = {
        to_email: 'kovdor24@yandex.ru',
        user_email: emailInput,
        tariff_name: tariffNameText,
        email_subject: `Новая заявка на статус Профи - HeatCalc.ru`,
        subject_text: `Новая заявка на статус Профи - HeatCalc.ru`,
        email_body: `Поступила новая заявка на активацию статуса Профи.\n\n• Email пользователя: ${emailInput}\n• Выбранный тариф: ${tariffNameText}\n\nПожалуйста, проверьте поступление оплаты в банке.`,
        message_text: `Поступила новая заявка на активацию статуса Профи.\n\n• Email пользователя: ${emailInput}\n• Выбранный тариф: ${tariffNameText}\n\nПожалуйста, проверьте поступление оплаты в банке.`
    };

    if (typeof emailjs !== 'undefined') {
        emailjs.send(emailjsServiceID, emailjsTemplateID, templateParams)
            .catch(err => console.error('Ошибка EmailJS:', err));
    } else {
        console.warn('Библиотека EmailJS не загружена');
    }

    // === 3. ЗАКРЫТИЕ ВСЕХ ВСПЛЫВАЮЩИХ ОКОН И УВЕДОМЛЕНИЕ ===
    // Закрываем окно оплаты
    closePaymentModal();

    // Закрываем главное окно тарифов (Подписка Профи) через штатный метод и принудительное скрытие
    if (typeof app !== 'undefined' && typeof app.closeModal === 'function') {
        app.closeModal();
    }
    const mainPricingModal = document.getElementById('custom_modal_overlay');
    if (mainPricingModal) {
        mainPricingModal.classList.remove('active');
        mainPricingModal.style.display = 'none';
    }

    // Закрываем окно профиля
    const profileModal = document.getElementById('profile_modal_overlay');
    if (profileModal) {
        profileModal.style.display = 'none';
    }

    // Закрываем окно авторизации
    const authModal = document.getElementById('auth_modal_overlay');
    if (authModal) {
        authModal.style.display = 'none';
    }

    // Закрываем все элементы с классом auth-modal-overlay для полной надежности
    document.querySelectorAll('.auth-modal-overlay').forEach(overlay => {
        overlay.style.display = 'none';
    });

    // Отображаем всплывающее уведомление пользователю
    app.alert('Спасибо! Мы проверяем поступление средств. Статус Профи будет активирован на email: ' + emailInput + ' в ближайшее время.');
}
window.notifyPayment = notifyPayment;
document.addEventListener('DOMContentLoaded', function () { app.init(); });

// Автоматическая генерация мульти-страничного документа перед печатью. Вынесена в отдельную
// именованную функцию (а не анонимный обработчик), чтобы её можно было вызвать напрямую из
// executeDownload() на мобильных/планшетах — там PDF скачивается через html2pdf() без
// настоящего window.print(), поэтому событие 'beforeprint' само по себе не сработает.
function prepareForPrint() {
    // Копия уже собрана и картинки дождались (флаг ставит executeDownload перед
    // window.print()): повторная сборка по 'beforeprint' только навредит — см.
    // ниже про метку и картинки. Выходим до очистки контейнера.
    if (typeof app !== 'undefined' && app._printBinReady) return;

    document.body.classList.remove('dark-mode');

    // 1. Создаем или очищаем скрытый контейнер, который увидит только принтер
    let printBin = document.getElementById('print_bin');
    if (!printBin) {
        printBin = document.createElement('div');
        printBin.id = 'print_bin';
        document.body.appendChild(printBin);
    }
    printBin.innerHTML = '';

    // Retrieve selected options from app.printOptions (default to true if undefined)
    const showEq = app.printOptions ? app.printOptions.eq : true;
    const showWorks = app.printOptions ? app.printOptions.works : true;
    const showHeatLossOpt = app.printOptions ? app.printOptions.heatLoss : true;
    const showSchemeOpt = app.printOptions ? app.printOptions.scheme : true;

    // Запоминаем текущее состояние
    let originalMode = app.state.viewMode;
    let printArea = document.getElementById('print-area');

    // Документ уходит наружу: названия без моделей, артикулов нет. Флаг читает
    // render() на время сборки печатной копии; перед возвратом интерфейса он снимается.
    app._exportShort = !app.printOptions || app.printOptions.shortNames !== false;

    // Сборка может прийти дважды подряд: executeDownload собирает копию заранее
    // (чтобы дождаться картинок), а потом window.print() поднимает 'beforeprint'
    // и собирает снова. Вторая сборка вредна дважды: клон наследовал метку
    // «спрятать от принтера» (шаг 5) — уходил пустой лист; и картинки в свежих
    // клонах не успевали к снимку страницы — половина миниатюр печаталась
    // пустыми клетками. Готовую копию не трогаем (проверка в начале функции),
    // а на случай сборки по Ctrl+P без предварительной — метку снимаем до
    // клонирования, шаг 5 вернёт её на место.
    if (printArea) printArea.classList.remove('hide-original-for-print');
    const liveSchemeEarly = document.getElementById('dynamic_scheme');
    if (liveSchemeEarly) liveSchemeEarly.classList.remove('hide-original-for-print');

    if (printArea) {
        // Раскладка по плану дома: данные те же, что уходят в ссылку клиенту
        let planViews = null;
        if (window.KpShare && showSchemeOpt && app.schemeOn()) { try { planViews = app.ufhPlanForShare(); } catch (e) { planViews = null; } }

        // --- ШАГ 1: ЛИСТ ОБОРУДОВАНИЯ ---
        if (showEq) {
            app.state.viewMode = 'equipment';
            app.render();
            let eqClone = printArea.cloneNode(true);
            eqClone.id = 'print_eq_clone';
            // Убираем схему и табы
            // Бланк гарантии печатается один раз и последним листом (шаг 6)
            const eqWp = eqClone.querySelector('#warranty_print'); if (eqWp) eqWp.remove();
            let eqScheme = eqClone.querySelector('#dynamic_scheme');
            if (eqScheme) eqScheme.remove();
            // В КП из всех схем идут только схема котельной (отдельным листом, шаг 3) и
            // раскладка радиаторов и тёплого пола по плану (отдельным разделом, шаг 2б, как
            // в ссылке). Остальные схемы-строки таблицы — автоматика, узлы, вода — не печатаем.
            const eqPlanRow = eqClone.querySelector('#ufh_plan_scheme_row');
            if (!eqPlanRow || !showSchemeOpt) planViews = null;
            eqClone.querySelectorAll('tr.scheme-row').forEach(tr => tr.remove());
            let eqTabs = eqClone.querySelector('.main-view-tabs');
            if (eqTabs) eqTabs.style.display = 'none';
            printBin.appendChild(eqClone);
        }

        // --- ШАГ 2: ЛИСТ МОНТАЖНЫХ РАБОТ (Доступно авторизованным пользователям на любом
        // тарифе — Базовый и Профи, только гость не имеет доступа к разделу работ) ---
        let isGuest = !app.state.tgUser;

        if (showWorks && !isGuest) {
            app.state.viewMode = 'works';
            app.render();
            let worksClone = printArea.cloneNode(true);
            worksClone.id = 'print_works_clone';
            if (showEq) {
                worksClone.classList.add('print-page-break'); // Разрыв страницы
            }
            const worksWp = worksClone.querySelector('#warranty_print'); if (worksWp) worksWp.remove();
            let worksScheme = worksClone.querySelector('#dynamic_scheme');
            if (worksScheme) worksScheme.remove();
            let wTabs = worksClone.querySelector('.main-view-tabs');
            if (wTabs) wTabs.style.display = 'none';

            // === ВЫРЕЗАЕМ ЛИШНИЕ КОЛОНКИ ДЛЯ ЭКОНОМИИ МЕСТА ===
            worksClone.querySelectorAll('table').forEach(table => {
                let headers = table.querySelectorAll('thead th');
                let hideIdx = [];
                // Ищем индексы ненужных колонок
                headers.forEach((th, idx) => {
                    let txt = th.innerText.trim().toUpperCase();
                    if (txt === 'БРЕНД' || txt === 'АРТИКУЛ' || txt === 'ФОТО') {
                        hideIdx.push(idx);
                    }
                });
                // Скрываем эти ячейки во всех строках
                if (hideIdx.length > 0) {
                    table.querySelectorAll('tr').forEach(row => {
                        let cells = row.children;
                        hideIdx.forEach(idx => {
                            if (cells[idx]) cells[idx].style.display = 'none';
                        });
                    });
                }
            });
            // ==================================================

            printBin.appendChild(worksClone);
        }

        // --- ШАГ 2а: РАЗДЕЛ «ВАШ ДОМ» — сразу после оборудования и работ, как на странице
        // клиента (invoice.html): город, теплопотери, «вы просили — мы учли», комнаты,
        // стоимость отопления, QR на онлайн-КП. Оформление то же, что в ссылке (kp_share.js);
        // нет модуля — прежняя разметка kpPersonalHtml ---
        if (app.kpHouseOn !== false) {
            let kpNode = null;
            try {
                const kpData = app.kpPersonalData();
                if (kpData && window.KpShare) {
                    const wr = app.warrantyFormEligible() ? app.warrantyLinkData() : null;
                    kpNode = window.KpShare.house(kpData, wr);
                } else if (kpData) {
                    const kpHtml = app.kpPersonalHtml(kpData, app._kpQr);
                    if (kpHtml) { kpNode = document.createElement('div'); kpNode.innerHTML = kpHtml; }
                }
            } catch (e) { kpNode = null; }
            if (kpNode) {
                const kpPage = document.createElement('div');
                kpPage.id = 'kp_personal_page';
                if (printBin.children.length > 0) kpPage.classList.add('print-page-break');
                kpPage.appendChild(kpNode);
                printBin.appendChild(kpPage);
            }
        }

        // --- ШАГ 2б: ПЛАН ОТОПЛЕНИЯ ДОМА — следом за «Ваш дом», как в ссылке (раздел «Тёплый
        // пол в вашем доме»): плана нет или оборудование не печатают — раздела нет ---
        if (planViews && planViews.length) {
            let planNode = null;
            try { planNode = window.KpShare.plan(planViews); } catch (e) { planNode = null; }
            if (planNode) {
                const planPage = document.createElement('div');
                planPage.id = 'kp_plan_page';
                if (printBin.children.length > 0) planPage.classList.add('print-page-break');
                planPage.appendChild(planNode);
                printBin.appendChild(planPage);
            }
        }

        // --- ШАГ 3: СХЕМА (На отдельном листе, независимо от раздела ОБОРУДОВАНИЕ/РАБОТЫ —
        // управляется отдельным чекбоксом в окне печати) ---
        if (showSchemeOpt && app.schemeOn()) {
            app.state.viewMode = 'equipment'; // Схема генерится только на этой вкладке
            app.render();
            let currentScheme = document.getElementById('dynamic_scheme');
            if (currentScheme) {
                let schemeClone = currentScheme.cloneNode(true);
                // Разрыв страницы нужен, только если перед схемой уже что-то напечатано
                // (иначе, если схема — первый выбранный раздел, получаем пустую первую страницу).
                if (printBin.children.length > 0) {
                    schemeClone.classList.add('print-page-break');
                }
                printBin.appendChild(schemeClone);
            }
        }

        // --- ШАГ 4: ТАБЛИЦА ТЕПЛОПОТЕРЬ (Подробный режим + готовый расчёт по комнатам,
        // управляется отдельным чекбоксом в окне печати) ---
        if (showHeatLossOpt && app.state.detailedRooms && app.state.showDetailedRoomsPanel) {
            let heatLossHtml = app.renderHeatLossTable();
            if (heatLossHtml) {
                let hlContainer = document.createElement('div');
                hlContainer.id = 'heat_loss_table_page';
                hlContainer.innerHTML = heatLossHtml;
                // Разрыв страницы нужен, только если перед таблицей уже что-то напечатано
                // (иначе, если теплопотери — единственный выбранный раздел, получаем пустую
                // первую страницу перед таблицей).
                if (printBin.children.length > 0) {
                    hlContainer.classList.add('print-page-break');
                }
                printBin.appendChild(hlContainer);
            }
        }

        // --- ШАГ 6: БЛАНК «ГАРАНТИЯ НА ОБЪЕКТ STOUT» — последним листом всего документа,
        // после схемы и таблицы теплопотерь. Живой блок (#warranty_print) собирает
        // render(); пустой (долю STOUT не набрали) в печать не идёт. ---
        // Оформление — как лист «Гарантия» на странице клиента (kp_share.js); нет модуля или
        // данных — прежний бланк.
        // Бланк печатается, только когда указаны адрес и заказчик (warrantyFormEligible): иначе
        // живой блок пуст. В окне «Объект и заказчик» об этом сказано.
        const wpLive = document.getElementById('warranty_print');
        let wNode = null;
        if (window.KpShare && app.kpWarrantyOn !== false && wpLive && wpLive.innerHTML.trim() && printBin.children.length > 0) {
            try {
                const tg = app.state.tgUser || {};
                const mgr = { name: app.formatShortName(tg) || '', phone: tg.phone || '', customCompany: app.state.customCompany || null };
                wNode = window.KpShare.warranty(app.warrantyLinkData(), mgr);
            } catch (e) { wNode = null; }
        }
        if (wNode) {
            const wpPage = document.createElement('div');
            wpPage.className = 'print-page-break';
            wpPage.appendChild(wNode);
            printBin.appendChild(wpPage);
        } else if (app.kpWarrantyOn !== false && wpLive && wpLive.innerHTML.trim() && printBin.children.length > 0) {
            const wpPage = document.createElement('div');
            wpPage.className = 'warranty-print';
            wpPage.innerHTML = wpLive.innerHTML;
            printBin.appendChild(wpPage);
        }

        // --- #16: ПРЕДУПРЕЖДЕНИЯ О НЕХВАТКЕ МОЩНОСТИ ---
        // Это технические замечания для монтажника (дефицит приборов по помещениям). В смету
        // для клиента они не идут никогда — на экране расчёта видны, на печати/в PDF скрыты.
        // Класс снимается в cleanupAfterPrint.
        document.body.classList.add('hide-warns-print');

        // --- ШАГ 5: ПРЯЧЕМ ОРИГИНАЛ ОТ ПРИНТЕРА ---
        printArea.classList.add('hide-original-for-print');
        let liveScheme = document.getElementById('dynamic_scheme');
        if (liveScheme) liveScheme.classList.add('hide-original-for-print');

        // Миниатюры в смете помечены loading="lazy": пока строка не показалась на
        // экране, файл не запрашивается вовсе. Печатная копия целиком лежит за
        // пределами экрана, поэтому в PDF половина фотографий уходила пустой
        // клеткой. Клонам ленивую загрузку снимаем — ждёт их app.awaitPrintImages().
        printBin.querySelectorAll('img').forEach(img => {
            img.loading = 'eager';
            img.decoding = 'sync';
            const src = img.getAttribute('src');
            if (src && !img.complete) img.setAttribute('src', src);
        });

        // Возвращаем интерфейс в исходное состояние
        app._exportShort = false;
        app.state.viewMode = originalMode;
        app.render();
    }
    app._exportShort = false;
}
window.addEventListener('beforeprint', prepareForPrint);

// Возврат к нормальной жизни после закрытия окна печати. Так же вынесена в именованную
// функцию — вызывается напрямую из executeDownload() после html2pdf() на мобильных/планшетах,
// где событие 'afterprint' не наступает (не было настоящего window.print()).
function cleanupAfterPrint() {
    if (app) { app._printBinReady = false; app._exportShort = false; }
    if (app && app.state && app.state.darkMode) {
        document.body.classList.add('dark-mode');
    }

    // Возвращаем видимость оригинальному интерфейсу
    let printArea = document.getElementById('print-area');
    let liveScheme = document.getElementById('dynamic_scheme');
    if (printArea) printArea.classList.remove('hide-original-for-print');
    if (liveScheme) liveScheme.classList.remove('hide-original-for-print');
    // #16: возвращаем предупреждения о нехватке мощности в интерфейс после печати
    document.body.classList.remove('hide-warns-print');

    // Очищаем корзину печати
    let printBin = document.getElementById('print_bin');
    if (printBin) printBin.innerHTML = '';
}
window.addEventListener('afterprint', cleanupAfterPrint);

// Датчик прокрутки для сужения шапки
window.addEventListener('scroll', function () {
    let header = document.querySelector('.site-header');
    if (header) {
        // Если прокрутили больше чем на 40 пикселей - включаем режим "узкой шапки"
        if (window.scrollY > 40) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    }
});